# Keys that are pure format strings or names: kept as-is, not translated.
SKIP = {"%", "%@", "%@ – %@", "%@: %@", "%lld", "%lld%%", "LimitLookUp"}

here = os.path.dirname(os.path.abspath(__file__))
path = os.path.join(here, "..", "Shared", "Localizable.xcstrings")
keys = sorted(set(T) | SKIP)
strings = {}
for k in keys:
    if k in SKIP:
        strings[k] = {"shouldTranslate": False}
        continue
    if k not in T:
        raise SystemExit(f"missing translation: {k!r}")
    assert len(T[k]) == len(L), k
    locs = {lang: {"stringUnit": {"state": "translated", "value": v}} for lang, v in zip(L, T[k])}
    locs["en"] = {"stringUnit": {"state": "translated", "value": k}}  # needed so English can be chosen in-app
    strings[k] = {"localizations": locs}
json.dump({"sourceLanguage": "en", "strings": strings, "version": "1.0"}, open(path, "w"), ensure_ascii=False, indent=2)
print(f"{len(strings)} keys written")
